// Français (France) UI catalog — partial by design (owner 2026-10-13: periodic translation; normal
// development maintains only zh-CN + en). Missing keys fall back to en at lookup time
// (i18n/index.tsx); `...modulesEn` first keeps every key present, the entries below override.
//
// Vocabulaire (2026-10-15, complément 638 clés) : profil (Profile), tour (turn), file (queue),
// délégation (delegation/ask), point de terminaison (endpoint), lancement rapide (quick launch),
// discussion latérale (side chat), favori (bookmark), note (tell/note), mise à niveau (upgrade),
// retour arrière (rollback), à sens unique (one-way), pré-vérification (preflight), lot (batch),
// préréglage (preset, notifications : présélection), épingler/désépingler (pin), bande (strip),
// replier/déplier (collapse/expand), rotation du {{director}} (rotate), passation (handoff),
// zone de notification (tray), navigateur intégré (in-app browser), workflow / job / skill / hook
// (inchangés), téléverser (upload). Produits et jetons inchangés : Cutex, Codex, Claude, Base URL,
// Job Service, Task Service, Claude Science, {{agent}} {{agents}} {{owner}} {{director}}.
